SELECT 

WHERE sp.deleted = 0
AND sp.counselor_id = #{counselorId}
AND sp.class_name = #{className}
AND sp.status = #{status}

    AND (u.real_name LIKE CONCAT('%', #{keyword}, '%')
         OR u.username LIKE CONCAT('%', #{keyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{keyword}, '%')
         OR sp.major LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY sp.class_name, sp.student_no, sp.id
LIMIT #{limit} OFFSET #{offset}

SELECT 

LEFT JOIN eval_summary m ON m.student_id = sp.user_id AND m.academic_term = #{term}
WHERE sp.deleted = 0 AND sp.status = 'active' AND m.id IS NULL
AND sp.counselor_id = #{counselorId}
ORDER BY sp.class_name, sp.student_no
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM student_profile sp
LEFT JOIN eval_summary m ON m.student_id = sp.user_id AND m.academic_term = #{term}
WHERE sp.deleted = 0 AND sp.status = 'active' AND m.id IS NULL
AND sp.counselor_id = #{counselorId}
